"""Split text into chunks of at most `max_characters` characters.

Characters are Unicode code points; no tokenizer is involved, so the size of
a chunk in a model's tokens is not known here. Each chunk ends at the last
boundary that falls in the second half of its allowed length, preferring a
paragraph break, then a line break, then the end of a sentence, then any
whitespace. A chunk with none of these is cut at exactly `max_characters`.
The boundary stays at the end of the chunk before it, so without overlap the
chunks joined with no separator are the text exactly.

With `overlap_characters`, each chunk after the first starts up to that many
characters before the previous chunk ended.
"""

import json
import re
import sys

TOOL = "chunk_text"
INPUTS = ("text", "max_characters", "overlap_characters")
REQUIRED = ("text", "max_characters")
SENTENCE_END = re.compile(r"[.!?][\"')\]]*\s")
WHITESPACE = re.compile(r"\s")


def fail(status, message):
    sys.stderr.buffer.write(message.encode("utf-8"))
    sys.exit(status)


def read_inputs():
    inputs = json.loads(sys.stdin.buffer.read().decode("utf-8"))

    for name in inputs:
        if name not in INPUTS:
            fail(2, f"{TOOL} does not take the input {name!r}.")

    for name in REQUIRED:
        if name not in inputs:
            fail(2, f"{TOOL} needs the input {name!r}.")

    return inputs


def is_integer(value):
    return isinstance(value, int) and not isinstance(value, bool)


def last_end(pattern, window):
    end = 0

    for match in pattern.finditer(window):
        end = match.end()

    return end


def boundary(window):
    least = len(window) // 2

    for separator in ("\n\n", "\n"):
        found = window.rfind(separator)

        if found != -1 and found + len(separator) > least:
            return found + len(separator)

    for pattern in (SENTENCE_END, WHITESPACE):
        end = last_end(pattern, window)

        if end > least:
            return end

    return len(window)


def chunks(text, size, overlap):
    result = []
    start = 0

    while start < len(text):
        if len(text) - start <= size:
            result.append(text[start:])
            break

        cut = start + boundary(text[start : start + size])
        result.append(text[start:cut])
        start = max(cut - overlap, start + 1)

    return result


inputs = read_inputs()
text = inputs["text"]
size = inputs["max_characters"]
overlap = inputs.get("overlap_characters", 0)

if not isinstance(text, str):
    fail(2, f"{TOOL} needs 'text' to be a string.")

if not is_integer(size) or size < 1:
    fail(2, f"{TOOL} needs 'max_characters' to be a whole number of at least 1.")

if not is_integer(overlap) or overlap < 0 or overlap >= size:
    fail(
        2,
        f"{TOOL} needs 'overlap_characters' to be a whole number from 0 to "
        f"one less than 'max_characters'.",
    )

result = chunks(text, size, overlap)

sys.stdout.buffer.write(json.dumps({"chunks": result}, ensure_ascii=False).encode("utf-8"))
